","type":"application/javascript","module-type":"startup"},"$:/plugins/tiddlywiki/aws/utils.js":{"title":"$:/plugins/tiddlywiki/aws/utils.js","text":"/*\
title: $:/plugins/tiddlywiki/aws/utils.js
type: application/javascript
module-type: library

AWS utility functions

\*/
/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

/*
Get a file from an S3 bucket
region:
bucketName:
title:
callback: invoked with (err,{body:,type:}
*/
function getFile(region,bucketName,title,callback) {
	// console.log("Reading file from S3",bucketName,title);
	var AWS = require("aws-sdk"),
		s3bucket = new AWS.S3({
			region: region
		}),
		params = {
			Bucket: bucketName,
			Key: title
		};
	s3bucket.getObject(params,function(err,data) {
		if(err) {
			return callback(err);
		}
		callback(null,{
			etag: data.ETag,
			version: data.VersionId,
			type: data.ContentType,
			body: data.Body.toString()
		});
	});
}

/*
Put a file to an S3 bucket
*/
function putFile(region,bucketName,title,text,type,callback) {
	// Log the write
	if($tw["lambda-result"]) {
		$tw["lambda-result"]["files-written"].push({bucket: bucketName,key: title});		
	}
	// console.log("Writing file to S3",bucketName,title,type);
	var AWS = require("aws-sdk"),
		s3bucket = new AWS.S3({
			region: region
		}),
		encoding = ($tw.config.contentTypeInfo[type] || {encoding: "utf8"}).encoding,
		params = {
			Bucket: bucketName,
			Key: title,
			Body: new Buffer(text,encoding),
			ContentType: type || "text/plain"
		};
	s3bucket.upload(params,function(err,data) {
		if(err) {
			return callback(err + " (writing " + title + " to " + bucketName + ", type " + type + ")");
		}
		callback(null,data);
	});
}

exports.putFile = putFile;
exports.getFile = getFile;
","type":"application/javascript","module-type":"library"},"$:/plugins/tiddlywiki/aws/lambda/handler":{"title":"$:/plugins/tiddlywiki/aws/lambda/handler","type":"text/plain","text":"/*
TiddlyWiki for AWS
*/

exports.handler = function(event,context,callback) {
	// Initialise the boot prefix
	global.$tw = _bootprefix();
	// Initialise the returned results
	$tw["lambda-result"] = {
		"files-written": []
	};
	// Some default package info
	$tw.packageInfo = lambdaPackageInfo;
	// Load any tiddlers from the package
	$tw.preloadTiddlerArray(lambdaTiddlers);
	// Decompress the event data if required
	if(typeof event.compressed === "string") {
		require("zlib").gunzip(Buffer.from(event.compressed,"base64"),function(err,buff) {
			if(err) {
				return callback(err);
			}
			boot(JSON.parse(buff.toString()));
	  });
	} else {
		boot(event);
	}

	function boot(event) {
		// Load any tiddlers from the event
		if(event.tiddlers) {
			$tw.preloadTiddlerArray(event.tiddlers);	
		}
		// Load the commands from the event
		$tw.boot.argv = (event.commands || []).slice(0);
		// Boot the TW5 app
		_boot($tw);
		$tw.boot.boot(function() {
			callback(null,$tw["lambda-result"]);
		});	
	}
}
