{"tiddlers":{"$:/plugins/tiddlywiki/googleanalytics/googleanalytics.js":{"title":"$:/plugins/tiddlywiki/googleanalytics/googleanalytics.js","text":"/*\
title: $:/plugins/tiddlywiki/googleanalytics/googleanalytics.js
type: application/javascript
module-type: startup

Runs Google Analytics with the measurement ID in the tiddler `$:/GoogleAnalyticsMeasurementID`

\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

// Export name and synchronous status
exports.name = "google-analytics";
exports.platforms = ["browser"];
exports.synchronous = true;

var CONFIG_CONSENT_REQUIRED_TITLE = "$:/config/cookie-consent-required", // "yes" or "no" (the default)
	CONSENT_TITLE = "$:/state/consent-banner/accepted"; // "": undeclared, "yes": accepted, "no": declined

exports.startup = function() {
	var hasInitialised = false,
		initialiseGoogleAnalytics = function() {
			console.log("Initialising Google Analytics");
			hasInitialised = true;
			var gaMeasurementID = $tw.wiki.getTiddlerText("$:/GoogleAnalyticsMeasurementID","").replace(/\n/g,"");
			var url ="https://www.googletagmanager.com/gtag/js?id=" + gaMeasurementID;
			window.dataLayer = window.dataLayer || [];
			window.gtag = function() { window.dataLayer?.push(arguments); };
			window.gtag("js",new Date());
			window.gtag("config",gaMeasurementID);
			const scriptElement = window.document.createElement("script");
			scriptElement.async = true;
			scriptElement.src = url;
			window.document.head.appendChild(scriptElement);
		};
	// Initialise now if consent isn't required
	if($tw.wiki.getTiddlerText(CONFIG_CONSENT_REQUIRED_TITLE) !== "yes") {
		initialiseGoogleAnalytics();
	} else {
		// Or has been granted already
		if($tw.wiki.getTiddlerText(CONSENT_TITLE) === "yes") {
			initialiseGoogleAnalytics();
		} else {
			// Or when our config tiddler changes
			$tw.wiki.addEventListener("change",function(changes) {
				if(changes[CONSENT_TITLE]) {
					if(!hasInitialised && $tw.wiki.getTiddlerText(CONSENT_TITLE) === "yes") {
						initialiseGoogleAnalytics();
					}
				}
			});
		}
	}
};



})();
","type":"application/javascript","module-type":"startup"},"$:/plugins/tiddlywiki/googleanalytics/readme":{"title":"$:/plugins/tiddlywiki/googleanalytics/readme","text":"This plugin enables you to use Google Analytics to track access to your online TiddlyWiki document.

By default, the user is not asked for permission before initialising Google Analytics. This plugin also optionally integrates with the "Consent Banner" plugin (also found in the official plugin library) so that Google Analytics is not initialised until the user grants explicit permission.

[[Source code|https://github.com/TiddlyWiki/TiddlyWiki5/blob/master/plugins/tiddlywiki/googleanalytics]]
"},"$:/plugins/tiddlywiki/googleanalytics/settings":{"title":"$:/plugins/tiddlywiki/googleanalytics/settings","caption":"Google Analytics","tags":"$:/tags/ControlPanel/SettingsTab","text":"''[[Google Analytics Measurement ID|$:/GoogleAnalyticsMeasurementID]]'': (mandatory) a code of the form `G-XXXXXXXXXX` where X are digits or uppercase letters<br/><$edit-text tiddler="$:/GoogleAnalyticsMeasurementID" default="" tag="input"/>

"},"$:/plugins/tiddlywiki/googleanalytics/usage":{"title":"$:/plugins/tiddlywiki/googleanalytics/usage","text":"!! Create a Google Analytics account

If you don't already have an account:

# Go to the Google Analytics website: http://www.google.com/analytics/
# Click the ''Access Google Analytics'' button and follow instructions to set up your account
# Enter the URL where the wiki is hosted
# Note the Tracking ID for this domain of the form `G-XXXXXXXXXX`

!! Install the plugin on your local copy of the TiddlyWiki

# ''Backup your TiddlyWiki''. Just in case
# Install the plugin via the plugin manager in control panel
# Save the TiddlyWiki andrefresh the page to load the plugin
# Go to [[$:/ControlPanel]] > Plugins tab and unfold the Google Analytics Plugin
# Go to the //settings// tab and edit the parameters
# Save the TiddlyWiki

!! Upload the new version of your TiddlyWiki

# Upload the saved TiddlyWiki to Tiddlyhost, GitHub, GitLab or other web host
# Return to your Google Analytics page to check that your site is being tracked
"}}}

