"},"$:/plugins/tiddlywiki/help/styles":{"title":"$:/plugins/tiddlywiki/help/styles","tags":"[[$:/tags/Stylesheet]]","text":"\rules only filteredtranscludeinline transcludeinline macrodef macrocallinline

.tc-help-panel {
	position: fixed;
	bottom: 0;
	right: 0;
	width: 310px;
	height: 400px;
	overflow: auto;
	-webkit-overflow-scrolling: touch;
	<<box-shadow "0px 0px 5px rgba(0, 0, 0, 0.3)">>
	border: 1px solid <<colour tiddler-border>>;
	background: <<colour tiddler-background>>;
	padding: 1em;
	margin: 0.5em;
	z-index: 1000;
}

dl.tc-help-cheatsheet {
	overflow: hidden;
}

dl.tc-help-cheatsheet .red {
	color: red;
}

.tc-help-cheatsheet > dt {
