title: $:/plugins/tiddlywiki/qrcode/barcodereader.js
type: application/javascript
module-type: widget

barcodereader widget for reading barcodes

\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var nextID = 0;

var BarCodeReaderWidget = function(parseTreeNode,options) {
	this.initialise(parseTreeNode,options);
};

/*
Inherit from the base widget class
*/
BarCodeReaderWidget.prototype = new Widget();

/*
Render this widget into the DOM
*/
BarCodeReaderWidget.prototype.render = function(parent,nextSibling) {
	var self = this;
	this.parentDomNode = parent;
	this.computeAttributes();
	// Make the child widgets
	this.makeChildWidgets();
	// Generate an ID for this element
	var id = "capture-widget-internal-" + nextID;
	nextID += 1;
	// Create the DOM node and render children
	var domNode = this.document.createElement("div");
	domNode.className = "tc-readcode-widget";
	domNode.setAttribute("width","300px");
	domNode.setAttribute("height","300px");
	domNode.id = id;
	parent.insertBefore(domNode,nextSibling);
	this.renderChildren(domNode,null);
	this.domNodes.push(domNode);
	// Setup the qrcode library
	if($tw.browser) {
		var __Html5QrcodeLibrary__ = require("$:/plugins/tiddlywiki/qrcode/html5-qrcode/html5-qrcode.js").__Html5QrcodeLibrary__;
		function onScanSuccess(decodedText, decodedResult) {
			self.invokeActionString(self.getAttribute("actionsSuccess",""),self,{},{
				format: decodedResult.result.format.formatName,
				text: decodedText
			});
			console.log("Scan result",decodedResult,decodedText);
		}
		function onScanFailure(errorMessage) {
			self.invokeActionString(self.getAttribute("actionsFailure",""),self,{},{
				error: errorMessage
			});
			console.log("Scan error",errorMessage);
		}
		var html5QrcodeScanner = new __Html5QrcodeLibrary__.Html5QrcodeScanner(
			id,
			{
				fps: 10,
				qrbox: 250
			}
		);
		html5QrcodeScanner.render(onScanSuccess,onScanFailure);
	}
};

/*
Selectively refreshes the widget if needed. Returns true if the widget or any of its children needed re-rendering
*/
BarCodeReaderWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes(),
		hasChangedAttributes = $tw.utils.count(changedAttributes) > 0;
	if(hasChangedAttributes) {
		return this.refreshSelf();
	}
	return this.refreshChildren(changedTiddlers) || hasChangedAttributes;
};

exports.barcodereader = BarCodeReaderWidget;

})();
","type":"application/javascript","module-type":"widget"},"$:/plugins/tiddlywiki/qrcode/docs/barcodereader":{"title":"$:/plugins/tiddlywiki/qrcode/docs/barcodereader","tags":"$:/tags/QRCodeDocs","caption":"barcodereader Widget","text":"The `<$barcodereader>` widget allows barcodes to be read from the device camera or from an image file. In the case of the camera, a live preview feed is shown to allow the barcode to be framed.

Note that for security reasons browsers restrict the operation of the camera to only work with web pages that have been loaded via HTTPS, or via localhost. Safari and Firefox allow usage from a file URI, but Chrome crashes when attempting to use the barcode reader from a file URI.

The `<$barcodereader>` widget has the following attributes:

|!Name |!Description |
|actionsSuccess |Action string to be executed when a code is successfully decoded |
|actionsFailure |Action string to be executed in the event of an error |

The following variables are passed to the ''actionsSuccess'' handler:

|!Name |!Description |
|format |Barcode format (see below) |
|text |Decoded text |

The following barcode formats are supported:

* 0: "QR_CODE"
* 1: "AZTEC"
* 2: "CODABAR"
* 3: "CODE_39"
* 4: "CODE_93"
* 5: "CODE_128"
* 6: "DATA_MATRIX"
* 7: "MAXICODE"
* 8: "ITF"
* 9: "EAN_13"
* 10: "EAN_8"
* 11: "PDF_417"
* 12: "RSS_14"
* 13: "RSS_EXPANDED"
* 14: "UPC_A"
* 15: "UPC_E"
* 16: "UPC_EAN_EXTENSION"

The following variables are passed to the ''actionsFailure'' handler:

|!Name |!Description |
|error |Error message |
"},"$:/plugins/tiddlywiki/qrcode/docs/qrcode":{"title":"$:/plugins/tiddlywiki/qrcode/docs/qrcode","tags":"$:/tags/QRCodeDocs","caption":"makeqr Macro","text":"The ''makeqr'' [[macro|Macros]] converts text data into an image of the corresponding QR code. The image is returned as [[base64-encoded data URI|https://developer.mozilla.org/en-US/docs/Web/HTTP/Basics_of_HTTP/Data_URIs]].

!! Parameters

;text
: The text to encode
;size
: The size of the image in pixels (defaults to 500)
;errorCorrectLevel
: Determines the amount of error correction applied to the image (see below, defaults to "M")
;fallback
: The fallback image to be returned in case of an error (see below)

The conversion will fail if the text is too long and/or complex and the macro will return the provided fallback image. If no fallback image is provided then an error image is generated.

The error correction level is a [[QR code feature|http://www.qrcode.com/en/about/error_correction.html]]:

|errorCorrectLevel |Redundancy |Use cases |h
|L | 7%|Clean environment, large amount of data |
|M | 15%|Default value, most common choice |
|Q | 25%|Dirty environment, small amount of data |
|H | 30%|~|

!! Examples

Making a QR code data URI for a simple string of text:

```
<<makeqr "Hello there!">>
```

Displaying a QR code for a simple string of text:

```
<img src=<<makeqr "Hello there!">> />
```

Displaying a QR code for a transcluded value (URL of the current wiki):

```
\define qr(content) <img src=<<makeqr text:"""$content$""">> />

<$transclude $variable="qr" content={{$:/info/url/full}} />
```
