"},"$:/plugins/tiddlywiki/railroad/readme":{"title":"$:/plugins/tiddlywiki/railroad/readme","created":"20150102163222184","modified":"20150119231005000","text":"This plugin provides a `<$railroad>` widget for generating railroad diagrams as SVG images.

Alternatively, the [[diagram notation|$:/plugins/tiddlywiki/railroad/syntax]] can be stored in a dedicated tiddler with its `type` field set to `text/vnd.tiddlywiki.railroad`, and that tiddler can simply be transcluded to wherever it is needed.

The plugin is based on [[a library by Tab Atkins|https://github.com/tabatkins/railroad-diagrams]], and has been extended to make it more flexible, including allowing components of a diagram to function as links or be transcluded from other tiddlers.
"},"$:/plugins/tiddlywiki/railroad/syntax-string":{"title":"$:/plugins/tiddlywiki/railroad/syntax-string","created":"20150103184022184","modified":"20150103184022184","text":"('"' text '"' | "'" text "'" | '"""' text '"""')"},"$:/plugins/tiddlywiki/railroad/syntax":{"title":"$:/plugins/tiddlywiki/railroad/syntax","created":"20150103184022184","modified":"20150119220342000","text":"
The railroad widget uses a special notation to construct the components defined below.

`x` and `y` here stand for any component.

Names (as opposed to quoted strings) are available when a value starts with a letter and contains only letters, digits, underscores, dots and hyphens.

---

; sequence
: <$railroad text=""" ["<-"] {x} ["->"] """/>

* A sequence of components
* The `<-` and `->` delimiters allow you to force a single component to be treated as a sequence. This is occasionally useful for spacing a diagram out

examples

<<<

```
x y z			sequence
```
<$railroad text=""" x y z """/>

```
<-x y z->		explicit sequence
```

<$railroad text=""" <- x y z -> """/>

<<<


---

; optional
: <$railroad text=""" "[" [":"] x "]" """/>
* A component that can be omitted
* The colon makes `x` appear straight ahead

examples

<<<

```
[:x]			optional, normally included
```
<$railroad text=""" [:x] """/>

```
[x]				optional, normally omitted
```

<$railroad text=""" [x] """/>

<<<


---

; repeated
: <$railroad text=""" "{" x [:"+" y] "}" """/>
* A list of one or more `x`
* The `+` suffix adds `y` as a separator between each `x` and the next

examples

<<<

```
{x}				one or more
```
<$railroad text=""" {x} """/>

```
{x +","}		one or more, comma-separated
```

<$railroad text=""" {x +","} """/>

<<<


---

; optional repeated
: <$railroad text=""" "[{" [":"] x [:"+" y] "}]" """/>
* An optional list of `x`, i.e. a list of zero or more `x`

examples

<<<

```
[{:x}]			zero or more, normally included
```

<$railroad text=""" [{:x}] """/>

```
[{:x +","}]		zero or more, comma-separated, normally included
```

<$railroad text=""" [{:x +","}] """/>

```
[{x}]			zero or more, normally omitted
```

<$railroad text=""" [{x}] """/>

```
[{x +","}]		zero or more, comma-separated, normally omitted
```

<$railroad text=""" [{x +","}] """/>

<<<



---

; choice
: <$railroad text=""" "(" {[:":"] x +"|"} ")" """/>
* A set of alternatives
* The colon indicates which branch appears straight ahead. By default, it's the first branch

examples

<<<

```
(x|y|z)			alternatives
```

<$railroad text=""" (x|y|z) """/>

```
(x|:y|z)		alternatives, normally y
```

<$railroad text=""" (x|:y|z) """/>

<<<


---

; string / terminal
: <$railroad text={{$:/plugins/tiddlywiki/railroad/syntax-string}}/>
* A literal or terminal component
* This follows the normal ~TiddlyWiki rules for quoted strings

examples

<<<

```
"x"				terminal
```

<$railroad text=""" "x" """/>

<<<


---

; nonterminal
: <$railroad text=""" (name | "<" string ">") """/>
* A nonterminal component, i.e. the name of another diagram

examples

<<<

```
<"x">			nonterminal
```

<$railroad text=""" <"x"> """/>

<<<


---

; comment
: <$railroad text=""" "/" string "/" """/>
* A comment

examples

<<<

```
/ "comment" /		comment
```

<$railroad text=""" / "comment" / """/>

<<<


---

; dummy
: <$railroad text=""" "-" """/>
* The absence of a component

examples

<<<

```
-		dummy
```

<$railroad text=""" - """/>

<<<


---

; link
: <$railroad text=""" "[[" x "|" (name|string) "]]" """/>
* A link to the tiddler title or URI given by the string or name

examples

<<<

```
[[x|"tiddler"]]		link
```

<$railroad text=""" [[x|"tiddler"]] """/>

<<<


---

; transclusion
: <$railroad text=""" "{{" (name|string) "}}" """/>
* Treats the content of another tiddler as diagram syntax and transcludes it into the current diagram

examples

<<<

```
{{"$:/plugins/tiddlywiki/railroad/example-transclusion"}}		transclusion

// "railroad transclusion example" text		<- text in the tidlder

```

<$railroad text=""" {{ "$:/plugins/tiddlywiki/railroad/example-transclusion" }} """/>

<<<


---

; arrow pragma
: <$railroad text=""" "\arrow" ("yes" | "no") """/>
* Controls whether repeat paths have an arrow on them
* Can be toggled on and off in mid-diagram, if desired

examples

<<<
```
<$railroad text="""
\arrow yes
[{:x}]
"""/>

```

<$railroad text="""\arrow yes [{:x}] """/>

```
<$railroad text="""
\arrow no
[{:x}]
"""/>
```

<$railroad text="""\arrow no [{:x}] """/>

<<<


---

; debug pragma
: <$railroad text=""" "\debug" """/>
* Causes the diagram to display its parse tree

examples

<<<

```
\debug
x
```

<$railroad text="""\debug x """/>

<<<


---

; start/end pragma
: <$railroad text=""" ("\start" |: "\end") ("none" |: "single" | "double") """/>
* Controls the style of the diagram's startpoint or endpoint
examples

<<<

```
\start none x
```

<$railroad text=""" \start none x """/>

```
\start double 
\end double
 x
```

<$railroad text=""" \start double 
\end double
x
"""/>

<<<

"},"$:/plugins/tiddlywiki/railroad/usage":{"title":"$:/plugins/tiddlywiki/railroad/usage","created":"20150102163222184","modified":"20150119231005000","text":"The content of the `<$railroad>` widget is ignored.

|!Attribute |!Description |!Default |
|text |Text in a special notation that defines the diagram's layout |-- |
|arrow |If set to `no`, repeat paths do not have an arrow on them |`yes` |
|start |Style of the startpoint: `single`, `double`, `none` |`single` |
|end |Style of the endpoint: `single`, `double`, `none` |`single` |
|debug |If set to `yes`, the diagram displays its parse tree |`no` |

These options can also be specified via pragmas in the diagram notation, or globally via a dictionary tiddler called `$:/config/railroad`:

```
arrow: yes
start: single
end: single
debug: no
```
"},"$:/plugins/tiddlywiki/railroad/railroad-diagrams.css":{"text":"\rules only filteredtranscludeinline transcludeinline macrodef macrocallinline macrocallblock

/* CSS modified for TiddlyWiki */

svg.railroad-diagram {
	background-color: <<colour background>>;
	border-radius: 5px;
}
/*
svg.railroad-diagram:hover {
	background-color: hsl(30,20%,96%);
}
*/
svg.railroad-diagram path,
svg.railroad-diagram rect {
	stroke-width: 2;
	stroke: <<colour message-border>>;
}
svg.railroad-diagram path {
	fill: <<colour background>>;
}
svg.railroad-diagram rect {
	fill: <<colour message-background>>;
}
svg.railroad-diagram text {
	font: 14px monospace;
	text-anchor: middle;
	fill: <<colour message-foreground>>;
}
svg.railroad-diagram text.label {
	text-anchor: start;
}
svg.railroad-diagram text.comment {
	font: italic 12px monospace;
}
svg.railroad-diagram path.arrow {
    stroke-width: 2;
}","type":"text/vnd.tiddlywiki","title":"$:/plugins/tiddlywiki/railroad/railroad-diagrams.css","tags":"$:/tags/Stylesheet"},"$:/plugins/tiddlywiki/railroad/railroad-diagrams.js":{"text":"(function(document) {
/* TiddlyWiki: modifications to the original library are commented like this */

/*
Railroad Diagrams
by Tab Atkins Jr. (and others)
http://xanthir.com
http://twitter.com/tabatkins
http://github.com/tabatkins/railroad-diagrams

This document and all associated files in the github project are licensed under CC0: http://creativecommons.org/publicdomain/zero/1.0/
This means you can reuse, remix, or otherwise appropriate this project for your own use WITHOUT RESTRICTION.
(The actual legal meaning can be found at the above link.)
Don't ask me for permission to use any part of this project, JUST USE IT.
I would appreciate attribution, but that is not required by the license.
*/

/*
This file uses a module pattern to avoid leaking names into the global scope.
The only accidental leakage is the name "temp".
The exported names can be found at the bottom of this file;
simply change the names in the array of strings to change what they are called in your application.

As well, several configuration constants are passed into the module function at the bottom of this file.
At runtime, these constants can be found on the Diagram class.
*/

var temp = (function(options) {
	function subclassOf(baseClass, superClass) {
		baseClass.prototype = Object.create(superClass.prototype);
		baseClass.prototype.$super = superClass.prototype;
	}

	function unnull(/* children */) {
		return [].slice.call(arguments).reduce(function(sofar, x) { return sofar !== undefined ? sofar : x; });
	}

	function determineGaps(outer, inner) {
		var diff = outer - inner;
		switch(Diagram.INTERNAL_ALIGNMENT) {
			case 'left': return [0, diff]; break;
			case 'right': return [diff, 0]; break;
			case 'center':
			default: return [diff/2, diff/2]; break;
		}
	}

	function wrapString(value) {
		return ((typeof value) == 'string') ? new Terminal(value) : value;
	}


	function SVG(name, attrs, text) {
		attrs = attrs || {};
		text = text || '';
		var el = document.createElementNS("http://www.w3.org/2000/svg",name);
		for(var attr in attrs) {
			el.setAttribute(attr, attrs[attr]);
		}
		el.textContent = text;
		return el;
	}

	function FakeSVG(tagName, attrs, text){
		if(!(this instanceof FakeSVG)) return new FakeSVG(tagName, attrs, text);
		if(text) this.children = text;
		else this.children = [];
		this.tagName = tagName;
		this.attrs = unnull(attrs, {});
		return this;
	};
	FakeSVG.prototype.format = function(x, y, width) {
		// Virtual
	};
	FakeSVG.prototype.addTo = function(parent) {
		if(parent instanceof FakeSVG) {
			parent.children.push(this);
			return this;
		} else {
			var svg = this.toSVG();
			parent.appendChild(svg);
			return svg;
		}
	};
	FakeSVG.prototype.toSVG = function() {
		var el = SVG(this.tagName, this.attrs);
		if(typeof this.children == 'string') {
			el.textContent = this.children;
		} else {
			this.children.forEach(function(e) {
				el.appendChild(e.toSVG());
			});
		}
		return el;
	};
	FakeSVG.prototype.toString = function() {
		var str = '<' + this.tagName;
		var group = this.tagName == "g" || this.tagName == "svg";
		for(var attr in this.attrs) {
			str += ' ' + attr + '="' + (this.attrs[attr]+'').replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '"';
		}
		str += '>';
		if(group) str += "\n";
		if(typeof this.children == 'string') {
			str += this.children.replace(/&/g, '&amp;').replace(/</g, '&lt;');
		} else {
			this.children.forEach(function(e) {
				str += e;
			});
		}
		str += '</' + this.tagName + '>\n';
		return str;
	}

	function Path(x,y,attrs) {
		if(!(this instanceof Path)) return new Path(x,y,attrs);
		FakeSVG.call(this, 'path', attrs);
		this.attrs.d = "M"+x+' '+y;
	}
	subclassOf(Path, FakeSVG);
	Path.prototype.m = function(x,y) {
		this.attrs.d += 'm'+x+' '+y;
		return this;
	}
	Path.prototype.h = function(val) {
		this.attrs.d += 'h'+val;
		return this;
	}
	Path.prototype.right = Path.prototype.h;
	Path.prototype.left = function(val) { return this.h(-val); }
	Path.prototype.v = function(val) {
		this.attrs.d += 'v'+val;
		return this;
	}
	Path.prototype.down = Path.prototype.v;
	Path.prototype.up = function(val) { return this.v(-val); }
	Path.prototype.arc = function(sweep){
		var x = Diagram.ARC_RADIUS;
		var y = Diagram.ARC_RADIUS;
		if(sweep[0] == 'e' || sweep[1] == 'w') {
			x *= -1;
		}
		if(sweep[0] == 's' || sweep[1] == 'n') {
			y *= -1;
		}
		if(sweep == 'ne' || sweep == 'es' || sweep == 'sw' || sweep == 'wn') {
			var cw = 1;
		} else {
			var cw = 0;
		}
		this.attrs.d += "a"+Diagram.ARC_RADIUS+" "+Diagram.ARC_RADIUS+" 0 0 "+cw+' '+x+' '+y;
		return this;
	}
	Path.prototype.format = function() {
		// All paths in this library start/end horizontally.
		// The extra .5 ensures a minor overlap, so there's no seams in bad rasterizers.
		this.attrs.d += 'h.5';
		return this;
	}
/* TiddlyWiki: added support for arbitrary straight lines */
	Path.prototype.line = function(dx,dy) {
		this.attrs.d += "l"+dx+" "+dy;
		return this;
	}

/* TiddlyWiki: added twOptions parameter, passing it to Start() and End() */
	function Diagram(twOptions, items) {
		if(!(this instanceof Diagram)) return new Diagram(twOptions, [].slice.call(arguments,1));
		FakeSVG.call(this, 'svg', {class: Diagram.DIAGRAM_CLASS});
		this.items = items.map(wrapString);
