		var t,matched,e;
		do {
			if(newLevel > currLevel) {
				for(t=currLevel; t<newLevel; t++) {
					var f = stack[stack.length-1];
					e = {type:"element",tag:this.element,children: []};
					stack.push(e);
					if(t ===0){
