/*
** Start with the normalize CSS reset, and then belay some of its effects
*/

{{$:/themes/tiddlywiki/vanilla/reset}}

input[type="search"] {
	outline-offset: initial;
}

button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
	outline: 2px solid <<colour primary>>;
	outline-offset: -2px;
	border-radius: 0.25em;
}

button:-moz-focusring, input:-moz-focusring, textarea:-moz-focusring, select:-moz-focusring {
	outline: 2px solid <<colour primary>>;
	outline-offset: -2px;
	border-radius: 0.25em;
}

/*
** Button default styles. Makes them look consistent for all browsers
*/
html button {
	line-height: 1.2;
	color: <<colour button-foreground>>;
	fill: <<colour button-foreground>>;
	background: <<colour button-background>>;
	border-color: <<colour button-border>>;
}

button:disabled svg {
	fill: <<colour muted-foreground>>;
}

/*
** Basic element styles
*/

html, body {
	font-family: {{$:/themes/tiddlywiki/vanilla/settings/fontfamily}};
	text-rendering: optimizeLegibility; /* Enables kerning and ligatures etc. */
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;
}

html:-webkit-full-screen {
	background-color: <<colour page-background>>;
}

body.tc-body {
	font-size: {{$:/themes/tiddlywiki/vanilla/metrics/fontsize}};
	line-height: {{$:/themes/tiddlywiki/vanilla/metrics/lineheight}};
	word-wrap: break-word;
	<<custom-background-datauri>>
	color: <<colour foreground>>;
	background-color: <<colour page-background>>;
	fill: <<colour foreground>>;
}

<<if-background-attachment """

body.tc-body {
	background-color: transparent;
}

""">>

/**
 * Correct the font size and margin on `h1` elements within `section` and
 * `article` contexts in Chrome, Firefox, and Safari.
 */

h1 {
	font-size: 2em;
}

h1, h2, h3, h4, h5, h6 {
	line-height: 1.2;
	font-weight: normal;
}

pre {
	display: block;
	margin-top: 1em;
	margin-bottom: 1em;
	word-break: normal;
	word-wrap: break-word;
	white-space: {{$:/themes/tiddlywiki/vanilla/options/codewrapping}};
	background-color: <<colour pre-background>>;
	border: 1px solid <<colour pre-border>>;
	padding: 0 3px 2px;
	border-radius: 3px;
	font-family: {{$:/themes/tiddlywiki/vanilla/settings/codefontfamily}};
}

code {
	color: <<colour code-foreground>>;
	background-color: <<colour code-background>>;
	border: 1px solid <<colour code-border>>;
	white-space: pre-wrap;
	padding: 0 3px 2px;
	border-radius: 3px;
	font-family: {{$:/themes/tiddlywiki/vanilla/settings/codefontfamily}};
}

blockquote {
	border-left: 5px solid <<colour blockquote-bar>>;
	margin-left: 25px;
	padding-left: 10px;
	quotes: "\201C""\201D""\2018""\2019";
}

blockquote > div {
	margin-top: 1em;
	margin-bottom: 1em;
}

blockquote.tc-big-quote {
	font-family: Georgia, serif;
	position: relative;
	background: <<colour pre-background>>;
	border-left: none;
	margin-left: 50px;
	margin-right: 50px;
	padding: 10px;
	border-radius: 8px;
}

blockquote.tc-big-quote cite:before {
	content: "\2014 \2009";
}

blockquote.tc-big-quote:before {
	font-family: Georgia, serif;
	color: <<colour blockquote-bar>>;
	content: open-quote;
	font-size: 8em;
	line-height: 0.1em;
	margin-right: 0.25em;
	vertical-align: -0.4em;
	position: absolute;
	left: -50px;
	top: 42px;
}

blockquote.tc-big-quote:after {
	font-family: Georgia, serif;
	color: <<colour blockquote-bar>>;
	content: close-quote;
	font-size: 8em;
	line-height: 0.1em;
	margin-right: 0.25em;
	vertical-align: -0.4em;
	position: absolute;
	right: -80px;
	bottom: -20px;
}

dl dt {
	font-weight: bold;
	margin-top: 6px;
}

textarea,
input[type=text],
input[type=search],
input[type=number],
input[type=password],
input[type=email],
input[type=tel],
input[type=url],
input[type=""],
input:not([type]) {
	color: <<colour foreground>>;
	background: <<colour background>>;
}

input[type="checkbox"] {
	vertical-align: middle;
}

input[type="search"]::-webkit-search-decoration,
input[type="search"]::-webkit-search-cancel-button,
input[type="search"]::-webkit-search-results-button,
input[type="search"]::-webkit-search-results-decoration {
	-webkit-appearance:none;
}

.tc-muted {
	color: <<colour muted-foreground>>;
}

svg.tc-image-button {
	padding: 0px 1px 1px 0px;
}

.tc-icon-wrapper > svg {
	width: 1em;
	height: 1em;
}

kbd {
	display: inline-block;
	padding: 3px 5px;
	font-size: 0.8em;
	line-height: 1.2;
	color: <<colour foreground>>;
	vertical-align: middle;
	background-color: <<colour background>>;
	border: solid 1px <<colour muted-foreground>>;
	border-bottom-color: <<colour muted-foreground>>;
	border-radius: 3px;
	box-shadow: inset 0 -1px 0 <<colour muted-foreground>>;
}

::selection {
	background-color: Highlight;
	color: HighlightText;
	background-color: <<colour selection-background>>;
	color: <<colour selection-foreground>>;
}

.tc-inline-style {
	background: <<colour highlight-background>>;
	color: <<colour highlight-foreground>>;
}

/* Markdown uses mark element to highlight */

mark {
	background: <<colour highlight-background>>;
	color: <<colour highlight-foreground>>;
}

form.tc-form-inline {
	display: inline;
}

/*
Markdown likes putting code elements inside pre elements
*/
pre > code {
	display: block;
	padding: 0.5em;
	border: none;
	white-space: {{$:/themes/tiddlywiki/vanilla/options/codewrapping}};
	background-color: inherit;
	color: inherit;
	overflow-x: auto;
}

/*
Table defaults
*/

table {
	border: 1px solid <<colour table-border>>;
	width: auto;
	max-width: 100%;
	caption-side: bottom;
	margin-top: 1em;
	margin-bottom: 1em;
	/* next 2 elements needed, since normalize 8.0.1 */
	border-collapse: collapse;
	border-spacing: 0;
}

table th, table td {
	padding: 0 7px 0 7px;
	border-top: 1px solid <<colour table-border>>;
	border-left: 1px solid <<colour table-border>>;
}

table thead tr td, table th {
	background-color: <<colour table-header-background>>;
	font-weight: bold;
}

table tfoot tr td {
	background-color: <<colour table-footer-background>>;
}

/*
Table utility classes
*/

/* Remove borders from table as used in eg: GettingStarted*/
.tc-table-no-border,
.tc-table-no-border th,
.tc-table-no-border td {
	border: initial;
}

/* First column in table width will fit to text.*/
/* This rule makes most sense with tc-first-link-nowrap*/
.tc-first-col-min-width td:nth-child(1) {
	width: 1%;
}

/*
** Utility classes work well with tables but also for other containers
*/

/* First link A element will not wrap */
.tc-first-link-nowrap:first-of-type a {
	white-space: nowrap;
}

/* Move the table to the center of the container */
.tc-center {
	margin-left: auto;
	margin-right: auto;
}

.tc-max-width {
	width: 100%;
}

.tc-max-width-80 {
	max-width: 80%;
}

/* Allow input and textarea to look like the ControlPanel inputs */
.tc-edit-max-width input,
.tc-edit-max-width textarea {
	width: 100%;
	padding: 3px;
}

/*
CSV parser plugin
*/

.tc-csv-table {
	white-space: nowrap;
}

.tc-csv-table th,
.tc-csv-table td {
	white-space: pre-line;
}

/*
Tiddler frame in story river
*/

.tc-tiddler-frame img,
.tc-tiddler-frame svg,
.tc-tiddler-frame canvas,
.tc-tiddler-frame embed,
.tc-tiddler-frame iframe {
	max-width: 100%;
}

.tc-tiddler-body > embed,
.tc-tiddler-body > iframe {
	width: 100%;
	height: 600px;
}

:root {
	color-scheme: {{{ [{$:/palette}get[color-scheme]] ~light }}};
}

/*
** Links
*/

button.tc-tiddlylink,
a.tc-tiddlylink {
	text-decoration: none;
	font-weight: 500;
	color: <<colour tiddler-link-foreground>>;
	-webkit-user-select: inherit; /* Otherwise the draggable attribute makes links impossible to select */
	-webkit-touch-callout: none; /* Prevents long presses from bringing up a link preview */
}

.tc-sidebar-lists a.tc-tiddlylink {
	color: <<colour sidebar-tiddler-link-foreground>>;
}

.tc-sidebar-lists a.tc-tiddlylink:hover {
	color: <<colour sidebar-tiddler-link-foreground-hover>>;
}

button.tc-tiddlylink:hover,
a.tc-tiddlylink:hover {
	text-decoration: underline;
}

a.tc-tiddlylink-resolves {
}

a.tc-tiddlylink-shadow {
	font-weight: bold;
}

a.tc-tiddlylink-shadow.tc-tiddlylink-resolves {
	font-weight: normal;
}

a.tc-tiddlylink-missing {
	font-style: italic;
}

a.tc-tiddlylink-external {
	text-decoration: underline;
	color: <<colour external-link-foreground>>;
	background-color: <<colour external-link-background>>;
}

a.tc-tiddlylink-external:visited {
	color: <<colour external-link-foreground-visited>>;
	background-color: <<colour external-link-background-visited>>;
}

a.tc-tiddlylink-external:hover {
	color: <<colour external-link-foreground-hover>>;
	background-color: <<colour external-link-background-hover>>;
}

.tc-drop-down a.tc-tiddlylink:hover {
	color: <<colour tiddler-link-background>>;
}

/*
** Drag and drop styles
*/

.tc-tiddler-dragger {
	position: relative;
	z-index: -10000;
}

.tc-tiddler-dragger-inner {
	position: absolute;
	top: -1000px;
	left: -1000px;
	display: inline-block;
	padding: 8px 20px;
	font-size: 16.9px;
	font-weight: bold;
	line-height: 20px;
	color: <<colour dragger-foreground>>;
	text-shadow: 0 1px 0 rgba(0, 0, 0, 1);
	white-space: nowrap;
	vertical-align: baseline;
	background-color: <<colour dragger-background>>;
	border-radius: 20px;
}

.tc-tiddler-dragger-cover {
	position: absolute;
	background-color: <<colour page-background>>;
}

.tc-page-container > .tc-dropzone {
	min-height: 100vh;
}

.tc-dropzone {
	position: relative;
}

.tc-dropzone.tc-dragover:before {
	z-index: 10000;
	display: block;
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	background: <<colour dropzone-background>>;
	text-align: center;
	content: "<<lingo DropMessage>>";
}

.tc-droppable > .tc-droppable-placeholder {
	display: none;
}

.tc-droppable.tc-dragover > .tc-droppable-placeholder {
	display: block;
	border: 2px dashed <<colour dropzone-background>>;
}

.tc-draggable {
	cursor: move;
}

.tc-sidebar-tab-open .tc-droppable-placeholder, .tc-tagged-draggable-list .tc-droppable-placeholder,
.tc-links-draggable-list .tc-droppable-placeholder {
	line-height: 2em;
	height: 2em;
}

.tc-sidebar-tab-open-item {
	position: relative;
}

.tc-sidebar-tab-open .tc-btn-invisible.tc-btn-mini svg {
	font-size: 0.7em;
	fill: <<colour muted-foreground>>;
}

/*
** Plugin reload warning
*/

.tc-plugin-reload-warning {
	z-index: 1000;
	display: block;
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	background: <<colour alert-background>>;
	text-align: center;
}

/*
** Buttons
*/

button svg, button img, label svg, label img {
	vertical-align: middle;
}

.tc-btn-invisible {
	padding: 0;
	margin: 0;
	background: none;
	border: none;
	cursor: pointer;
	color: <<colour foreground>>;
	fill: <<colour foreground>>;
}

button:disabled.tc-btn-invisible  {
	cursor: default;
	color: <<colour muted-foreground>>;
}

.tc-btn-boxed {
	font-size: 0.6em;
	padding: 0.2em;
	margin: 1px;
	background: none;
	border: 1px solid <<colour tiddler-controls-foreground>>;
	border-radius: 0.25em;
}

html body.tc-body .tc-btn-boxed svg {
	font-size: 1.6666em;
}

.tc-btn-boxed:hover {
	background: <<colour muted-foreground>>;
	color: <<colour background>>;
}

html body.tc-body .tc-btn-boxed:hover svg {
	fill: <<colour background>>;
}

.tc-btn-rounded {
	font-size: 0.5em;
	line-height: 2;
	padding: 0em 0.3em 0.2em 0.4em;
	margin: 1px;
	border: 1px solid <<colour muted-foreground>>;
	background: <<colour muted-foreground>>;
	color: <<colour background>>;
	border-radius: 2em;
}

html body.tc-body .tc-btn-rounded svg {
	font-size: 1.6666em;
	fill: <<colour background>>;
}

.tc-btn-rounded:hover {
	border: 1px solid <<colour muted-foreground>>;
	background: <<colour background>>;
	color: <<colour muted-foreground>>;
}

html body.tc-body .tc-btn-rounded:hover svg {
	fill: <<colour muted-foreground>>;
}

.tc-btn-icon svg {
	height: 1em;
	width: 1em;
	fill: <<colour muted-foreground>>;
}


.tc-btn-text {
	margin-left: 7px;
}

/* used for documentation "fake" buttons */
.tc-btn-standard {
	line-height: 1.8;
	color: #667;
	background-color: #e0e0e0;
	border: 1px solid #888;
	padding: 2px 1px 2px 1px;
	margin: 1px 4px 1px 4px;
}

.tc-btn-big-green {
	display: inline-block;
	padding: 8px;
	margin: 4px 8px 4px 8px;
	background: <<colour download-background>>;
	color: <<colour download-foreground>>;
	fill: <<colour download-foreground>>;
	border: none;
	border-radius: 2px;
	font-size: 1.2em;
	line-height: 1.4em;
	text-decoration: none;
}

.tc-btn-big-green svg,
.tc-btn-big-green img {
	height: 2em;
	width: 2em;
	vertical-align: middle;
	fill: <<colour download-foreground>>;
}

.tc-primary-btn {
	background: <<colour primary>>;
}

.tc-sidebar-lists input {
	color: <<colour foreground>>;
}

.tc-sidebar-lists button {
	color: <<colour sidebar-button-foreground>>;
	fill: <<colour sidebar-button-foreground>>;
}

.tc-sidebar-lists button.tc-btn-mini {
	color: <<colour sidebar-muted-foreground>>;
}

.tc-sidebar-lists button.tc-btn-mini:hover {
	color: <<colour sidebar-muted-foreground-hover>>;
}

.tc-sidebar-lists button small {
	color: <<colour foreground>>;
}

button svg.tc-image-button, button .tc-image-button img {
	height: 1em;
	width: 1em;
}

.tc-unfold-banner {
	position: absolute;
	padding: 0;
	margin: 0;
	background: none;
	border: none;
	width: 100%;
	width: calc(100% + 2px);
	margin-left: -43px;
	text-align: center;
	border-top: 2px solid <<colour tiddler-info-background>>;
	margin-top: 4px;
}

.tc-unfold-banner:hover {
	background: <<colour tiddler-info-background>>;
	border-top: 2px solid <<colour tiddler-info-border>>;
}

.tc-unfold-banner svg, .tc-fold-banner svg {
	height: 0.75em;
	fill: <<colour tiddler-controls-foreground>>;
}

.tc-unfold-banner:hover svg, .tc-fold-banner:hover svg {
	fill: <<colour tiddler-controls-foreground-hover>>;
}

.tc-fold-banner {
	position: absolute;
	padding: 0;
	margin: 0;
	background: none;
	border: none;
	width: 23px;
	text-align: center;
	margin-left: -35px;
	top: 6px;
	bottom: 6px;
}

.tc-fold-banner:hover {
	background: <<colour tiddler-info-background>>;
}

@media (max-width: <<sidebarbreakpoint-minus-one>>) {

	.tc-unfold-banner {
		position: static;
		width: calc(100% + 59px);
	}

	.tc-fold-banner {
		width: 16px;
		margin-left: -16px;
		font-size: 0.75em;
	}

}

/*
** Tags and missing tiddlers
*/

.tc-tag-list-item {
	position: relative;
	display: inline-block;
}

.tc-tags-wrapper {
	margin: 4px 0 14px 0;
}

.tc-tags-wrapper .tc-tag-list-item {
	margin-right: 7px;
}

.tc-missing-tiddler-label {
	font-style: italic;
	font-weight: normal;
	display: inline-block;
	font-size: 11.844px;
	line-height: 14px;
	white-space: nowrap;
	vertical-align: baseline;
}

.tc-block-tags-dropdown > .tc-btn-invisible:hover {
	background-color: <<colour primary>>;
}

button.tc-tag-label, span.tc-tag-label {
	display: inline-block;
	padding: 0.16em 0.7em;
	font-size: 0.9em;
	font-weight: normal;
	line-height: 1.2em;
	color: <<colour tag-foreground>>;
	white-space: break-spaces;
	vertical-align: baseline;
	background-color: <<colour tag-background>>;
	border-radius: 1em;
}

.tc-sidebar-scrollable .tc-tag-label {
	text-shadow: none;
}

.tc-untagged-separator {
	border: 0;
	height: 1px;
	background: <<colour tab-divider>>;
}

button.tc-untagged-label {
	background-color: <<colour untagged-background>>;
}

.tc-tag-label svg, .tc-tag-label img {
	height: 1em;
	width: 1em;
	margin-right: 3px;
	margin-bottom: 1px;
	vertical-align: bottom;
}

.tc-edit-tags button.tc-remove-tag-button svg {
	font-size: 0.7em;
	vertical-align: middle;
}

.tc-tag-manager-table .tc-tag-label {
}

.tc-tag-manager-tag {
	width: 100%;
}

button.tc-btn-invisible.tc-remove-tag-button {
	outline: none;
}

.tc-tag-button-selected,
.tc-list-item-selected a.tc-tiddlylink, a.tc-list-item-selected {
	background-color: <<colour primary>>;
	color: <<colour tiddler-background>>;
}

/*
** Page layout
*/

.tc-topbar {
	position: fixed;
	z-index: 1200;
}

.tc-topbar-left {
	left: 29px;
	top: 5px;
}

.tc-topbar-right {
	top: 5px;
	right: 29px;
}

@media (max-width: <<sidebarbreakpoint-minus-one>>) {

	.tc-topbar-right {
		right: 10px;
	}

}

.tc-topbar button {
	padding: 8px;
}

.tc-topbar svg {
	fill: <<colour muted-foreground>>;
}

.tc-topbar button:hover svg {
	fill: <<colour foreground>>;
}

@media (max-width: <<sidebarbreakpoint-minus-one>>) {

	.tc-show-sidebar-btn svg.tc-image-chevron-left, .tc-hide-sidebar-btn svg.tc-image-chevron-right {
		transform: rotate(-90deg);
	}

}

.tc-sidebar-header {
	color: <<colour sidebar-foreground>>;
	fill: <<colour sidebar-foreground>>;
}

.tc-sidebar-header .tc-title a.tc-tiddlylink-resolves {
	font-weight: normal;
}

.tc-sidebar-header .tc-sidebar-lists p {
	margin-top: 3px;
	margin-bottom: 3px;
}

.tc-sidebar-header .tc-missing-tiddler-label {
	color: <<colour sidebar-foreground>>;
}

.tc-advanced-search input {
	width: 60%;
}

.tc-search a svg {
	width: 1.2em;
	height: 1.2em;
	vertical-align: middle;
}

.tc-page-controls {
	margin-top: 14px;
	margin-bottom: 14px;
	font-size: 1.5em;
}

.tc-page-controls .tc-drop-down {
	font-size: 1rem;
}

.tc-page-controls button {
	margin-right: 0.5em;
}

.tc-page-controls a.tc-tiddlylink:hover {
	text-decoration: none;
}

.tc-page-controls img {
	width: 1em;
}

.tc-page-controls svg {
	fill: <<colour sidebar-controls-foreground>>;
}

.tc-page-controls button:hover svg, .tc-page-controls a:hover svg {
	fill: <<colour sidebar-controls-foreground-hover>>;
}

.tc-sidebar-lists .tc-menu-list-item {
	white-space: nowrap;
}

.tc-menu-list-count {
	font-weight: bold;
}

.tc-menu-list-subitem {
	padding-left: 7px;
}

.tc-story-river {
	position: relative;
}

@media (max-width: <<sidebarbreakpoint-minus-one>>) {

	.tc-sidebar-header {
		padding: 14px;
		min-height: 32px;
		margin-top: {{$:/themes/tiddlywiki/vanilla/metrics/storytop}};
		transition:  min-height {{$:/config/AnimationDuration}}ms ease-in-out, padding-top {{$:/config/AnimationDuration}}ms ease-in-out, padding-bottom {{$:/config/AnimationDuration}}ms ease-in-out;
	}

	<<if-no-sidebar """

		.tc-sidebar-header {
			min-height: 0;
			padding-top: 0;
			padding-bottom: 0;
		}

	""">>

	.tc-story-river {
		position: relative;
		padding: 0;
	}
}

@media (min-width: <<sidebarbreakpoint>>) {

	.tc-message-box {
		margin: 21px -21px 21px -21px;
	}

	.tc-sidebar-scrollable {
		position: fixed;
		top: {{$:/themes/tiddlywiki/vanilla/metrics/storytop}};
		left: {{$:/themes/tiddlywiki/vanilla/metrics/storyright}};
		bottom: 0;
		right: 0;
		overflow-y: auto;
		overflow-x: auto;
		-webkit-overflow-scrolling: touch;
		margin: 0 0 0 -42px;
		padding: 71px 0 28px 42px;
	}

	html[dir="rtl"] .tc-sidebar-scrollable {
		left: auto;
		right: {{$:/themes/tiddlywiki/vanilla/metrics/storyright}};
	}

	.tc-story-river {
		position: relative;
		left: {{$:/themes/tiddlywiki/vanilla/metrics/storyleft}};
		top: {{$:/themes/tiddlywiki/vanilla/metrics/storytop}};
		width: {{$:/themes/tiddlywiki/vanilla/metrics/storywidth}};
		padding: 42px 42px 42px 42px;
	}

<<if-no-sidebar "

	.tc-story-river {
		width: calc(100% - {{$:/themes/tiddlywiki/vanilla/metrics/storyleft}});
	}

">>

	.tc-story-river.tc-static-story-river {
		margin-right: 0;
		padding-right: 42px;
	}

}

@media print {

	body.tc-body {
		background-color: transparent;
	}

	.tc-sidebar-header, .tc-topbar {
		display: none;
	}

	.tc-story-river {
		margin: 0;
		padding: 0;
	}

	.tc-story-river .tc-tiddler-frame {
		margin: 0;
		border: none;
		padding: 0;
	}
}

/*
** Tiddler styles
*/

.tc-tiddler-frame {
	position: relative;
	margin-bottom: 28px;
	background-color: <<colour tiddler-background>>;
	border: 1px solid <<colour tiddler-border>>;
}

{{$:/themes/tiddlywiki/vanilla/sticky}}

.tc-tiddler-info {
	overflow: hidden;
	padding: 14px 42px 14px 42px;
	background-color: <<colour tiddler-info-background>>;
	border-top: 1px solid <<colour tiddler-info-border>>;
	border-bottom: 1px solid <<colour tiddler-info-border>>;
}

.tc-tiddler-info p {
	margin-top: 3px;
	margin-bottom: 3px;
}

.tc-tiddler-info .tc-tab-buttons button.tc-tab-selected {
	background-color: <<colour tiddler-info-tab-background>>;
	border-bottom: 1px solid <<colour tiddler-info-tab-background>>;
}

@media (max-width: <<sidebarbreakpoint-minus-one>>) {

	.tc-tiddler-info {
		padding: 14px 14px 14px 14px;
	}

}

.tc-view-field-table {
	width: 100%;
}

.tc-view-field-name {
	width: 1%; /* Makes this column be as narrow as possible */
	white-space: nowrap;
	vertical-align: top;
	text-align: right;
	font-style: italic;
	font-weight: normal;
}

.tc-view-field-value {
	word-break: break-all;
}

@media (max-width: <<sidebarbreakpoint-minus-one>>) {
	.tc-tiddler-frame {
		padding: 14px 14px 14px 14px;
		margin-bottom: .5em;
	}

	.tc-tiddler-info {
		margin: 0 -14px 0 -14px;
	}
}

@media (min-width: <<sidebarbreakpoint>>) {
	.tc-tiddler-frame {
		padding: 28px 42px 42px 42px;
		width: {{$:/themes/tiddlywiki/vanilla/metrics/tiddlerwidth}};
		border-radius: 2px;
	}

<<if-no-sidebar "

	.tc-tiddler-frame {
		width: 100%;
	}

">>

	.tc-tiddler-info {
		margin: 0 -42px 0 -42px;
	}
}

.tc-site-title,
.tc-titlebar {
	font-weight: normal;
	font-size: 2.35em;
	line-height: 1.35em;
	color: <<colour tiddler-title-foreground>>;
	margin: 0;
}

.tc-site-title {
	color: <<colour site-title-foreground>>;
}

.tc-tiddler-title-icon {
	vertical-align: middle;
	margin-right: .1em;
}

.tc-tiddler-title-icon svg {
	width: 0.9em;
	height: 0.9em;
}

.tc-system-title-prefix {
	color: <<colour muted-foreground>>;
}

.tc-tiddler-lazy-loading {
	height: 4px;
	width: 100%;
	background: no-repeat linear-gradient(<<colour background>> 0 0),no-repeat linear-gradient(<<colour background>> 0 0),<<colour primary>>;
	background-size: 60% 100%;
	animation: animation-loading-progress 3s infinite;
}

@keyframes animation-loading-progress {
	0%   {background-position:-150% 0,-150% 0}
	66%  {background-position: 250% 0,-150% 0}
	100% {background-position: 250% 0, 250% 0}
}

.tc-titlebar h2 {
	font-size: 1em;
	display: inline;
}

.tc-titlebar img {
	height: 1em;
}

.tc-subtitle {
	font-size: 0.9em;
	color: <<colour tiddler-subtitle-foreground>>;
	font-weight: normal;
}

.tc-subtitle .tc-tiddlylink {
	margin-right: .3em;
}

.tc-tiddler-missing .tc-title {
	font-style: italic;
	font-weight: normal;
}

.tc-tiddler-frame .tc-tiddler-controls {
	float: right;
	padding: 3px; /* make space for outline */
}

.tc-tiddler-controls .tc-drop-down {
	font-size: 0.6em;
}

.tc-tiddler-controls .tc-drop-down .tc-drop-down {
	font-size: 1em;
}

.tc-tiddler-controls > span > button,
.tc-tiddler-controls > span > span > button,
.tc-tiddler-controls > span > span > span > button {
	vertical-align: baseline;
	margin-left:5px;
